import{_ as r,o as t,c as a,ah as o}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Catalogue et banques QCM","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/catalogue.md","filePath":"src/guide/coordinateur/catalogue.md"}'),n={name:"guide/coordinateur/catalogue.md"};function s(i,e,l,u,c,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="catalogue-et-banques-qcm" tabindex="-1">Catalogue et banques QCM <a class="header-anchor" href="#catalogue-et-banques-qcm" aria-label="Permalink to &quot;Catalogue et banques QCM&quot;">​</a></h1><p>Le Coordinateur pédagogique tient le catalogue des formations et les questions du test d&#39;admission. L&#39;Administrateur peut faire la même chose. Tout se passe dans la rubrique <strong>Formation</strong>.</p><h2 id="le-catalogue" tabindex="-1">Le catalogue <a class="header-anchor" href="#le-catalogue" aria-label="Permalink to &quot;Le catalogue&quot;">​</a></h2><p><strong>Formation → Catalogue</strong> liste les programmes (les « référentiels ») avec leur code, leur catégorie, leurs formats, leur durée et leur statut : <strong>Brouillon</strong>, <strong>Publié</strong> ou <strong>Archivé</strong>. Seul un programme publié est visible sur le site NextBoxx.</p><h3 id="creer-un-programme" tabindex="-1">Créer un programme <a class="header-anchor" href="#creer-un-programme" aria-label="Permalink to &quot;Créer un programme&quot;">​</a></h3><p><strong>Nouveau programme</strong> demande un code, un titre, une catégorie et, pour la catégorie Parcours Métiers, s&#39;il s&#39;agit du <strong>package Développement Web &amp; Mobile</strong> (700 h). Le code commence par le préfixe de la catégorie suivi de deux chiffres (par exemple <code>NB.FP.01</code>). <strong>Le code, la catégorie et le package ne changent plus après la création</strong> : le code est la clé définitive du programme.</p><p>Le contenu pédagogique se saisit <strong>une fois par programme</strong> : objectifs, méthodes pédagogiques, prérequis, logistique, et les <strong>blocs de compétences</strong> dans leur ordre d&#39;enseignement, chacun avec sa durée en semaines (le total est comparé à la durée du programme). Chaque bloc porte le <strong>code de son carnet de notes Sève</strong> (<code>KURA-BLOC-{id}</code>), que les formateurs reportent dans Sève.</p><p>Les <strong>formats</strong> proposés sont à cocher : distanciel, hybride, présentiel.</p><h3 id="publier-depublier-archiver" tabindex="-1">Publier, dépublier, archiver <a class="header-anchor" href="#publier-depublier-archiver" aria-label="Permalink to &quot;Publier, dépublier, archiver&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Condition</th></tr></thead><tbody><tr><td><strong>Publier</strong></td><td>Au moins un format, des objectifs et au moins un bloc. L&#39;écran liste ce qui manque</td></tr><tr><td><strong>Dépublier</strong> ou <strong>Archiver</strong></td><td>Impossible si une cohorte ouverte, confirmée ou en cours en dépend</td></tr><tr><td><strong>Restaurer en brouillon</strong></td><td>Pour un programme archivé</td></tr><tr><td><strong>Supprimer</strong></td><td>Seulement un brouillon jamais publié</td></tr></tbody></table><h3 id="la-grille-tarifaire" tabindex="-1">La grille tarifaire <a class="header-anchor" href="#la-grille-tarifaire" aria-label="Permalink to &quot;La grille tarifaire&quot;">​</a></h3><p>Le prix n&#39;est <strong>jamais saisi librement</strong> : il vient de la <strong>grille tarifaire</strong>, selon la catégorie et le format. <strong>Formation → Catalogue → Grille tarifaire</strong> montre les prix en vigueur (en FCFA, hors taxe) et permet de <strong>programmer un changement</strong> à partir d&#39;une date. Un changement ne s&#39;applique qu&#39;aux <strong>cohortes ouvertes après cette date</strong> : il n&#39;est jamais rétroactif, et une cohorte déjà ouverte garde ses prix.</p><h2 id="les-banques-qcm" tabindex="-1">Les banques QCM <a class="header-anchor" href="#les-banques-qcm" aria-label="Permalink to &quot;Les banques QCM&quot;">​</a></h2><p>Le test d&#39;admission puise dans une banque de <strong>20 questions par programme</strong>. <strong>Catalogue → Banques QCM</strong> donne l&#39;état de chaque banque : <strong>Validée</strong>, <strong>À valider</strong> ou <strong>Absente</strong>. Sans banque validée, les candidats ne peuvent pas passer le test et <strong>aucune cohorte de ce programme ne peut s&#39;ouvrir</strong>.</p><p>Seuls le Coordinateur pédagogique et l&#39;Administrateur y ont accès. Les formateurs et les conseillers n&#39;y accèdent pas.</p><h3 id="importer" tabindex="-1">Importer <a class="header-anchor" href="#importer" aria-label="Permalink to &quot;Importer&quot;">​</a></h3><ol><li>Téléchargez le <strong>modèle</strong> de la catégorie : un classeur <code>.xlsx</code> avec un onglet par programme non archivé, nommé par son code.</li><li>Remplissez chaque onglet : <strong>exactement 20 lignes</strong>, avec les colonnes <code>énoncé</code>, <code>choix_1</code> à <code>choix_4</code> et <code>réponse_correcte</code> (le numéro du bon choix, de 1 à 4).</li><li>Choisissez la catégorie, le classeur, puis <strong>Importer</strong>.</li></ol><p>Chaque onglet est traité <strong>indépendamment</strong> : un onglet conforme crée un lot en brouillon, un onglet en erreur (structure incorrecte, code inconnu, 18 lignes au lieu de 20, réponse absente des choix) est rejeté seul, avec la <strong>ligne et la colonne</strong> fautives. Un rapport par onglet s&#39;affiche. Le fichier n&#39;est <strong>jamais conservé</strong>, en succès comme en échec : seul son nom est tracé.</p><h3 id="valider" tabindex="-1">Valider <a class="header-anchor" href="#valider" aria-label="Permalink to &quot;Valider&quot;">​</a></h3><p>L&#39;import et la validation sont <strong>deux actions distinctes</strong>. Ouvrez la banque du programme, relisez les questions, puis <strong>Valider la banque</strong>. Les questions des autres lots du programme sont alors retirées du tirage (elles restent en base).</p><ul><li>Un <strong>nouvel import</strong> ne remplace jamais une banque validée : il crée un lot à valider, et <strong>l&#39;ancienne banque reste en service</strong> jusqu&#39;à la validation du nouveau lot. On peut ainsi réimporter un seul onglet pour corriger un programme.</li><li><strong>Modifier une question validée</strong> la repasse « À valider » : la banque doit être validée à nouveau pour être utilisée.</li></ul><p>La banque est à relire <strong>chaque année</strong>.</p>',22)])])}const m=r(n,[["render",s]]);export{p as __pageData,m as default};
